expression:
grel:if(isBlank(value),
  with(cells["DISTRITO"].value, distrito,
    if(distrito == "CARABANCHEL", "11",
      if(distrito == "MONCLOA-ARAVACA", "9",
        if(distrito == "RETIRO", "3",
          if(distrito == "VICALVARO", "19",
            if(distrito == "VILLAVERDE", "17", value)
          )
        )
      )
    )
  ),
  value
)

description:
